        searchInput.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence value,int start,int count,int after){}public void onTextChanged(CharSequence value,int start,int before,int count){ui.removeCallbacks(delayedSearch);searchVersion++;finding=false;searchHit=null;totalMatches=matchNumber=0;searchQuery="";searchResults.clear();resultCopies.clear();resultsLoading=false;if(resultsAdapter!=null)resultsAdapter.notifyDataSetChanged();showResults(!value.toString().trim().isEmpty());if(moreResults!=null)moreResults.setVisibility(View.GONE);matchCount.setText(value.toString().trim().isEmpty()?"Enter words or a sender":"Searching…");updateSearchButtons();adapter.notifyDataSetChanged();if(value.toString().trim().isEmpty())return;ui.postDelayed(delayedSearch,350);}public void afterTextChanged(android.text.Editable value){}});
